mapper.insert:
INSERT INTO T_MORNING_BRIEF (
       USER_ID
      ,ENABLED_YN
) VALUES (
       #{userId}
      ,#{enabledYn}
)
ON CONFLICT (USER_ID) DO UPDATE
   SET ENABLED_YN = EXCLUDED.ENABLED_YN
      ,UPD_DAY    = NOW()

mapper.update:
UPDATE T_MORNING_BRIEF
   SET LAST_SENT_DAY = #{today}
      ,UPD_DAY       = NOW()
 WHERE 1=1
   AND USER_ID = #{userId}
   AND (LAST_SENT_DAY IS NULL OR LAST_SENT_DAY < #{today})

UPDATE T_MORNING_BRIEF
   SET LAST_SENT_DAY = #{lastSentDay}
      ,UPD_DAY       = NOW()
 WHERE 1=1
   AND USER_ID       = #{userId}
   AND LAST_SENT_DAY = #{today}
